from pathlib import Path
import markdown,re
r=Path.cwd(); body=markdown.markdown((r/'README.md').read_text(encoding='utf-8'),extensions=['tables','fenced_code','toc'])
body=re.sub(r'<li>\[ \] (.*?)</li>',r'<li class="todo"><label><input type="checkbox" class="progress-check"> \1</label></li>',body)
# Keep every chapter as its own searchable unit. The same links work in both editions.
chunks=re.split(r'(?=<h2 )',body); body=''.join('<section class="chapter">'+c+'</section>' for c in chunks)
nav=''.join(f'<a href="#{id}">{re.sub("<.*?>","",label)}</a>' for id,label in re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body))
head='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Compute Playground • The interactive book</title>
<style>
:root{color-scheme:light;--ink:#213c43;--paper:#fffdf8;--accent:#186960}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.7 Georgia,serif}aside{position:fixed;inset:0 auto 0 0;width:275px;padding:28px 22px;background:#eef2eb;overflow:auto;font:14px/1.6 system-ui}aside strong{display:block;font-size:21px;margin-bottom:6px}aside a{display:block;padding:6px 0}aside label{display:block;margin-top:16px}aside input{width:100%;padding:10px;margin:16px 0 8px;border:1px solid #8da39a;border-radius:4px}main{margin-left:275px;max-width:1120px;padding:40px 70px 100px}h1,h2,h3,button,label,input,summary{font-family:system-ui}h1{font-size:44px;line-height:1.1}h2{font-size:29px;line-height:1.3;border-top:1px solid #c9d4cb;padding-top:30px;margin-top:45px}h3{font-size:21px}a{color:#14675f;text-underline-offset:3px}a:hover{color:#003b34}p{max-width:78ch}table{border-collapse:collapse;width:100%;font:14px/1.6 system-ui;display:block;overflow:auto}td,th{padding:10px;border-bottom:1px solid #d9e1da;text-align:left}th{background:#edf1e9}pre{overflow:auto;background:#edf1e9;padding:20px;font:13px/1.7 Consolas,monospace;position:relative}code{font-family:Consolas,monospace;font-size:.88em}details{padding:16px 20px;background:#f0f3eb;border-left:3px solid var(--accent);margin:20px 0}summary{cursor:pointer;font-weight:600}button{padding:10px 16px;background:#186960;color:white;border:0;border-radius:4px;font-size:15px;cursor:pointer;margin:8px 8px 8px 0}button:hover{background:#104d46}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #b06b16;outline-offset:3px}.copy{display:block;margin-left:auto!important;font-size:12px;padding:5px 10px;margin:0 0 8px 10px}img{max-width:100%;height:auto}#toy{padding:20px 26px;border:1px solid #a9bdb0;margin:26px 0}#toy label{display:inline-block;margin-right:20px;font-size:14px}#toy input{width:75px;padding:6px}output{display:block;font:600 18px/1.6 system-ui;margin:12px 0}.note{font:14px/1.6 system-ui;color:#52675e}.todo{list-style:none}.progress-check{width:18px;height:18px;vertical-align:middle;accent-color:#186960}.chapter{scroll-margin-top:20px}#search-status,#progress{font-size:13px}.quiz-answer{font-weight:bold}footer{margin-top:50px;font-size:14px}@media(max-width:850px){aside{position:static;width:auto}aside nav{display:none}main{margin:0;padding:25px}h1{font-size:35px}table{font-size:13px}}@media print{aside,button,#toy{display:none}main{margin:0;padding:0}.chapter{display:block!important}details{break-inside:avoid}}
</style><aside><strong>Compute Playground</strong><span>CDEF Computing<br>The interactive field book</span><label for="search">Find a chapter</label><input id="search" type="search" placeholder="Try VM, CPU, security…"><div id="search-status" role="status"></div><div id="progress" role="status"></div><nav>'''
lab='''<section id="toy" aria-labelledby="toy-title"><h2 id="toy-title">Try the idea before opening the app</h2><p>Edge has 4 pretend helpers and 4 GB of table space. Book a job, then stop it. The numbers change.</p><label>CPU per job <input id="toy-cpu" type="number" min="1" max="4" value="2"></label><label>RAM per job (GB) <input id="toy-ram" type="number" min="1" max="4" value="1"></label><br><button id="book">Book one job</button><button id="stop">Stop latest job</button><button id="reset">Reset toy</button><output id="toy-state" aria-live="polite"></output><p id="toy-message" role="status"></p><p class="note">This teaching toy only tracks one node. The Python simulator also models all three nodes, processing, placement policies, VMs and ownership. The book does not change the app.</p><details><summary>Prediction game: after booking two jobs needing 2 CPU each, can Edge take a third?</summary><p class="quiz-answer">No. Both jobs use all 4 CPU units. Stop one first to free 2 units.</p></details></section>'''
script='''<script>
const chapters=[...document.querySelectorAll('.chapter')],q=document.querySelector('#search');q.addEventListener('input',()=>{const term=q.value.trim().toLowerCase();let n=0;chapters.forEach(c=>{const show=!term||c.textContent.toLowerCase().includes(term);c.hidden=!show;if(show)n++});document.querySelector('#search-status').textContent=term?`${n} matching sections. Clear search to see everything.`:''});document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{q.value='';chapters.forEach(c=>c.hidden=false);document.querySelector('#search-status').textContent=''}));
document.querySelectorAll('pre').forEach(pre=>{const b=document.createElement('button');b.className='copy';b.textContent='Copy';b.type='button';b.setAttribute('aria-label','Copy code block');const code=pre.querySelector('code');b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(code.textContent);b.textContent='Copied'}catch(e){b.textContent='Select text to copy';const r=document.createRange();r.selectNodeContents(code);getSelection().removeAllRanges();getSelection().addRange(r)}setTimeout(()=>b.textContent='Copy',2000)});pre.prepend(b)});
const checks=[...document.querySelectorAll('.progress-check')];let saved=[];try{saved=JSON.parse(localStorage.getItem('compute-playground-checks')||'[]')}catch(e){}function progress(){document.querySelector('#progress').textContent=`Show-and-tell checklist: ${checks.filter(c=>c.checked).length} / ${checks.length} complete`;}checks.forEach((c,i)=>{c.checked=!!saved[i];c.addEventListener('change',()=>{try{localStorage.setItem('compute-playground-checks',JSON.stringify(checks.map(c=>c.checked)))}catch(e){}progress()})});progress();
let jobs=[];const state=document.querySelector('#toy-state'),message=document.querySelector('#toy-message');function draw(){state.textContent=`CPU free: ${4-jobs.reduce((s,j)=>s+j.cpu,0)} / 4 · RAM free: ${4-jobs.reduce((s,j)=>s+j.ram,0)} / 4 GB · Active jobs: ${jobs.length}`;}document.querySelector('#book').onclick=()=>{const cpu=Number(document.querySelector('#toy-cpu').value),ram=Number(document.querySelector('#toy-ram').value);if(!Number.isInteger(cpu)||!Number.isInteger(ram)||cpu<1||ram<1||cpu>4||ram>4){message.textContent='Choose whole numbers from 1 to 4.';return}if(jobs.reduce((s,j)=>s+j.cpu,0)+cpu>4||jobs.reduce((s,j)=>s+j.ram,0)+ram>4){message.textContent='Rejected: Edge does not have enough free CPU or RAM. Stop a job first.';return}jobs.push({cpu,ram});message.textContent='Booked! The resources stay reserved until you stop the job.';draw()};document.querySelector('#stop').onclick=()=>{message.textContent=jobs.pop()?'Stopped! Its CPU and RAM are free again.':'Nothing to stop. No extra resources are created.';draw()};document.querySelector('#reset').onclick=()=>{jobs=[];message.textContent='Fresh start.';draw()};draw();
</script>'''
(r/'README.html').write_text(head+nav+'</nav></aside><main>'+lab+body+'<footer>Compute Playground · CDEF Computing · Offline companion to README.md</footer></main>'+script+'</html>',encoding='utf-8')
print('Interactive book generated')
